#!/usr/bin/env python3\n\"\"\"IPv6 range port scanner.\n\nUsage: python3 ipv6_port_scanner.py <cidr> <port1,port2,...>\nPrints JSON list of reachable IPs per port.\n\"\"\"\nimport sys, json, socket, ipaddress\n\ndef scan_range(cidr, ports):\n    results = {}\n    net = ipaddress.IPv6Network(cidr, strict=False)\n    for port in ports:\n        open_ips = []\n        for ip in net.hosts():\n            s = socket.socket(socket.AF_INET6, socket.SOCK_STREAM)\n            s.settimeout(1)\n            try:\n                s.connect((str(ip), port))\n                open_ips.append(str(ip))\n            except Exception:\n                pass\n            finally:\n                s.close()\n        results[str(port)] = open_ips\n    return results\n\ndef main():\n    if len(sys.argv) != 3:\n        print(json.dumps({\"error\":\"Usage: <cidr> <port1,port2,...>\"}))\n        sys.exit(1)\n    cidr = sys.argv[1]\n    ports = [int(p) for p in sys.argv[2].split(',') if p.strip().isdigit()]\n    out = scan_range(cidr, ports)\n    print(json.dumps(out))\n\nif __name__ == \"__main__\":\n    main()